draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  // Nine symbols for 81 (9x9)
  for (let i = 0; i < 3; i++) {
    for (let j = 0; j < 3; j++) {
      ctx.beginPath();
      ctx.arc(W / 2 - 100 + i * 70, H / 2 - 50 + j * 70, 20, 0, 2 * Math.PI);
      ctx.fill();
    }
  }
  // oscillating circle in the middle to represent infinity
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 10 + 5 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.restore();
}
